<?php get_header(); $author = kimpu_public_author_data( get_queried_object_id() ); ?>
<main id="primary" class="site-main author-page section"><div class="container blog-container"><div class="author-profile-header"><?php if ( $author ) : ?><div class="author-profile-avatar"><?php echo $author['avatar']; ?></div><div><h1><?php echo esc_html( $author['name'] ); ?></h1><?php if ( $author['bio'] ) : ?><p><?php echo esc_html( $author['bio'] ); ?></p><?php endif; ?><?php if ( $author['url'] ) : ?><a href="<?php echo esc_url( $author['url'] ); ?>" rel="me noopener"><?php esc_html_e( 'Visit website', 'kimpu-multipurpose' ); ?></a><?php endif; ?></div><?php endif; ?></div><div class="blog-layout blog-sidebar-<?php echo esc_attr( kimpu_blog_sidebar_position() ); ?><?php echo kimpu_blog_sidebar_active() ? ' has-blog-sidebar' : ''; ?>" style="--blog-sidebar-width:<?php echo esc_attr( kimpu_blog_mod( 'sidebar_width', '280px' ) ); ?>"><div class="blog-main"><h2 class="archive-subheading"><?php esc_html_e( 'Articles by this author', 'kimpu-multipurpose' ); ?></h2><?php if ( have_posts() ) : ?><div class="blog-results blog-layout-<?php echo esc_attr( kimpu_blog_layout() ); ?>"><?php kimpu_blog_render_loop(); ?></div><?php kimpu_blog_pagination(); else : ?><?php get_template_part( 'template-parts/blog/empty-state' ); ?><?php endif; ?></div><?php if ( kimpu_blog_sidebar_active() ) : ?><aside class="blog-sidebar" aria-label="<?php esc_attr_e( 'Author sidebar', 'kimpu-multipurpose' ); ?>"><?php dynamic_sidebar( 'blog-sidebar' ); ?></aside><?php endif; ?></div></div></main>
<?php get_footer(); ?>
